class Solution {
public:
    int calculate(string s) {
        stack<int> st;
        int n = 0;
        char op = '+';

        s += '+';

        for(char c : s){
            if(c == ' ') continue;

            if(isdigit(c)){
                n = n * 10 + (c - '0');
                continue;
            }

            if(op == '+') st.push(n);
            else if(op == '-') st.push(-n);
            else if(op == '*'){
                int top = st.top(); st.pop();
                st.push(top * n);
            }
            else if(op == '/'){
                int top = st.top(); st.pop();
                st.push(top / n);
            }

            op = c;
            n = 0;
        }

        int res = 0;
        while(!st.empty()){
            res += st.top();
            st.pop();
        }

        return res;
    }
};

class Solution {
public:
    int calculate(string s) {
        stack<int> st;
        long res = 0;
        long curr = 0;
        int sign = 1;

        for (char c : s) {
            if (isdigit(c)) {
                curr = curr * 10 + (c - '0');
            } else if (c == '+') {
                res += sign * curr;
                sign = 1;
                curr = 0;
            } else if (c == '-') {
                res += sign * curr;
                sign = -1;
                curr = 0;
            } else if (c == '(') {
                st.push(res);
                st.push(sign);
                res = 0;
                sign = 1;
            } else if (c == ')') {
                res += sign * curr;
                curr = 0;
                res *= st.top(); st.pop();
                res += st.top(); st.pop();
            }
        }

        res += sign * curr;
        return res;
    }
};

